#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int v; struct Node *l, *r; } Node;
static Node *mk(int v) { Node *n = malloc(sizeof(Node)); n->v = v; n->l = n->r = NULL; return n; }

static int height(Node *n) { return n ? 1 + (height(n->l) > height(n->r) ? height(n->l) : height(n->r)) : 0; }
static int count(Node *n)  { return n ? 1 + count(n->l) + count(n->r) : 0; }
static int leaves(Node *n) {
    if (!n) return 0;
    if (!n->l && !n->r) return 1;
    return leaves(n->l) + leaves(n->r);
}

int main(void) {
    Node *a = mk(1), *b = mk(2), *c = mk(3), *d = mk(4), *e = mk(5), *f = mk(6);
    a->l = b; a->r = c; b->l = d; b->r = e; c->r = f;
    printf("节点数 = %d\n", count(a));
    printf("树高   = %d\n", height(a));
    printf("叶子数 = %d\n", leaves(a));
    printf("说明: 三者都是后序遍历，先算子树再在根处合并\n");
    return 0;
}
